public bool IsValidBST(TreeNode root) {
    var stack = new Stack<TreeNode>();
    long prev = long.MinValue;
    var node = root;
    while (node != null || stack.Count > 0) {
        while (node != null) { stack.Push(node); node = node.left; }   // all the way left
        node = stack.Pop();                                            // next in ascending order
        if (node.val <= prev) return false;
        prev = node.val;
        node = node.right;
    }
    return true;
}

