public int KthSmallest(TreeNode root, int k) {
    var stack = new Stack<TreeNode>();
    var node = root;
    while (true) {
        while (node != null) { stack.Push(node); node = node.left; }
        node = stack.Pop();
        if (--k == 0) return node.val;    // the k-th popped in-order is the k-th smallest
        node = node.right;
    }
}
